package com.example.starter.salinity.exception;

import org.springframework.http.HttpStatus;

/**
 * 业务异常基类：携带 HTTP 状态码与机器可读错误码。
 */
public abstract class BusinessException extends RuntimeException {

    /**
     * @param message 人类可读错误说明
     */
    protected BusinessException(String message) {
        super(message);
    }

    /**
     * @return 对应的 HTTP 状态码
     */
    public abstract HttpStatus status();

    /**
     * @return 机器可读错误码
     */
    public abstract String code();
}

package com.example.starter.salinity.exception;

import org.springframework.http.HttpStatus;

/**
 * 请求参数或业务状态不满足要求，返回 422 UNPROCESSABLE_ENTITY。
 * 覆盖：越界值、跨航次质控、缺深度封存、封存后替换、勘误引用不存在等。
 */
public class UnprocessableException extends BusinessException {

    /**
     * @param message 错误说明
     */
    public UnprocessableException(String message) {
        super(message);
    }

    @Override
    public HttpStatus status() {
        return HttpStatus.UNPROCESSABLE_ENTITY;
    }

    @Override
    public String code() {
        return "UNPROCESSABLE";
    }
}

package com.example.starter.salinity.exception;

import org.springframework.http.HttpStatus;

/**
 * 冲突异常，返回 409 CONFLICT：采样编号相同但内容不同、请求幂等键与其他内容冲突等。
 */
public class ConflictException extends BusinessException {

    /**
     * @param message 错误说明
     */
    public ConflictException(String message) {
        super(message);
    }

    @Override
    public HttpStatus status() {
        return HttpStatus.CONFLICT;
    }

    @Override
    public String code() {
        return "CONFLICT";
    }
}

package com.example.starter.salinity.exception;

import org.springframework.http.HttpStatus;

/**
 * 资源不存在，返回 404。
 */
public class NotFoundException extends BusinessException {

    /**
     * @param message 错误说明
     */
    public NotFoundException(String message) {
        super(message);
    }

    @Override
    public HttpStatus status() {
        return HttpStatus.NOT_FOUND;
    }

    @Override
    public String code() {
        return "NOT_FOUND";
    }
}

package com.example.starter.salinity.support;

import org.springframework.stereotype.Component;

import java.time.Instant;

/**
 * 业务时钟：默认返回系统 UTC 时间，测试可替换为固定/步进时钟。
 */
@Component
public class BusinessClock {

    /**
     * @return 当前时刻（UTC）
     */
    public Instant now() {
        return Instant.now();
    }
}

