     */
    public List<Correction> findCorrectionsByVoyage(String voyageCode) {
        return jdbcClient.sql("""
                        SELECT * FROM corrections WHERE voyage_code = :voyageCode
                        ORDER BY id ASC
                        """)
                .param("voyageCode", voyageCode)
                .query(CORRECTION_MAPPER)
                .list();
    }
